/** Synthetic data for OFFLINE UI rendering; generated by the real domain handlers/SQLite adapter. */
import {fixture,plant,issue,tool,PNG} from '../test/helpers.mjs';
import {uid,after} from '../src/lib.js';
import {savePhoto} from '../src/media.js';
const f=await fixture();
try{
 const p=await plant(f.store,'Зелёный Борис'),q=await plant(f.store,'Огуречный профсоюз');
 await tool(f.store,'update_plant',{id:p.id,expected_version:p.version,display_name:p.display_name,profile:'Томат у окна. Общий вид и нижние листья.'});
 await tool(f.store,'update_plant',{id:q.id,expected_version:q.version,display_name:q.display_name,profile:'Грядка огурцов. Проверки без лишней суеты.'});
 const i=await issue(f.store,p);
 await tool(f.store,'save_hypothesis',{id:uid(),issue_id:i.id,title:'Возможная смена освещения',status:'ACTIVE',reasoning:'Нужно сопоставить одинаковый ракурс и одинаковое освещение; причинность пока не установлена.'});
 await tool(f.store,'create_experiment',{id:uid(),issue_id:i.id,title:'Наблюдение при одинаковом освещении',change_text:'Пока только план: фиксировать снимки в одном месте.',success_criteria:'Сравнимые фотографии позволяют оценить новые симптомы.',evaluate_at:after(3*86400000)});
 await tool(f.store,'create_followup',{id:uid(),plant_id:p.id,issue_id:i.id,type:'REQUEST_PHOTO',context:'Общий вид и крупно нижние листья',due_at:after(86400000)});
 const second=await issue(f.store,p);
 await tool(f.store,'close_issue',{issue_id:second.id,request_id:uid(),expected_version:second.version,user_confirmed:true,outcome:'UNKNOWN',reason:'Пользователь остановил учебное расследование',result_text:'Подтверждённого результата нет: сопоставимых фотографий недостаточно.'});
 for(let n=0;n<2;n++){const ph=await savePhoto(f.store,{captured_at:after(-(n+1)*86400000),view_tag:'WHOLE_PLANT'},PNG);await tool(f.store,'resolve_input',{input_id:ph.input_id,plant_id:p.id,method:'confirmed',user_confirmed:true,reason:'Синтетическая тестовая привязка'});}
 const data={plants:await tool(f.store,'get_plants'),settings:await tool(f.store,'get_settings'),cases:{},entities:{},lists:{}};
 for(const plant of data.plants.plants){data.cases[plant.id]=await tool(f.store,'get_case_file',{plant_id:plant.id});data.entities['plant:'+plant.id]=plant;for(const type of ['issue','hypothesis','experiment','followup','journal','observation','photo']){const result=await tool(f.store,'list_records',{plant_id:plant.id,type});data.lists[plant.id+':'+type]=result;for(const entity of result.items)data.entities[type+':'+entity.id]=entity;}}
 console.log(JSON.stringify(data));
}finally{f.close();}
